const query = $json.query || $json;
const sheetId = query.sheetId || $json.sheetId;

if (!sheetId || typeof sheetId !== 'string' || sheetId.trim() === '') {
  throw new Error('Missing sheetId query parameter');
}

return [
  {
    json: {
      sheetId: sheetId.trim(),
      query: query
    }
  }
];

const txsNodes = $('Read Transactions1').all();
const rawTxs = txsNodes && txsNodes.length > 0 ? txsNodes.map(i => i.json) : [];
const txs = rawTxs.filter(t => t && Object.keys(t).length > 0 && t.amount !== undefined && t.amount !== '' && String(t.type || '').toLowerCase() !== 'deleted');

const insightsNodes = $('Read Insights1').all();
const rawInsights = insightsNodes && insightsNodes.length > 0 ? insightsNodes.map(i => i.json) : [];
const insights = rawInsights.filter(i => i && Object.keys(i).length > 0 && (i.insights || i.paramData || i.insight || i.advice));

const now = new Date();
const nowMs = now.getTime();
const oneDayMs = 24 * 60 * 60 * 1000;
const sevenDaysAgoMs = nowMs - (7 * oneDayMs);
const thirtyDaysAgoMs = nowMs - (30 * oneDayMs);

let totalCredit = 0;
let totalDebit = 0;
let totalDebitWeek = 0;
let totalDebitMonth = 0;

let catAllTime = {};
let catMonthly = {};
let catWeekly = {};

let trendDaily = {};
let uniqueActiveDates = new Set();
let txDates = [];

const parseSheetDate = (raw) => {
  const str = String(raw || '').trim();
  if (!str) return '';
  if (/^\d{5}(\.\d+)?$/.test(str)) {
    const num = parseFloat(str);
    const ms = (num - 25569) * 86400 * 1000;
    const d = new Date(ms);
    if (!isNaN(d.getTime())) return d.toISOString().split('T')[0];
  }
  const dmyMatch = str.match(/^(\d{1,2})[-/](d{1,2})[-/](d{4})/);
  if (dmyMatch) {
    const day = dmyMatch[1].padStart(2, '0');
    const month = dmyMatch[2].padStart(2, '0');
    const year = dmyMatch[3];
    return year + '-' + month + '-' + day;
  }
  const ymdMatch = str.match(/^(\d{4})[-/](d{1,2})[-/](d{1,2})/);
  if (ymdMatch) {
    const year = ymdMatch[1];
    const month = ymdMatch[2].padStart(2, '0');
    const day = ymdMatch[3].padStart(2, '0');
    return year + '-' + month + '-' + day;
  }
  const parsed = new Date(str);
  if (!isNaN(parsed.getTime())) {
    return parsed.toISOString().split('T')[0];
  }
  return '';
};

txs.forEach(t => {
  const cleanAmtStr = String(t.amount || '').replace(/[^0-9.]/g, '');
  const amt = parseFloat(cleanAmtStr);
  if (isNaN(amt) || amt <= 0) return;

  const rawType = String(t.type || '').toLowerCase().trim();
  const isCredit = rawType === 'credit' || rawType === 'income';
  const cat = (t.category && String(t.category).trim()) || 'Other';

  const rawDateStr = String(t.date_of_transaction || t.date || t.timestamp || '').trim();
  let dayKey = parseSheetDate(rawDateStr);
  let parsedMs = dayKey ? new Date(dayKey).getTime() : NaN;

  if (!dayKey || isNaN(parsedMs)) {
    dayKey = now.toISOString().split('T')[0];
    parsedMs = nowMs;
  }

  txDates.push(parsedMs);
  uniqueActiveDates.add(dayKey);

  if (!trendDaily[dayKey]) {
    trendDaily[dayKey] = { date: dayKey, count: 0, credit: 0, debit: 0, net: 0 };
  }
  trendDaily[dayKey].count += 1;

  if (isCredit) {
    totalCredit += amt;
    trendDaily[dayKey].credit += amt;
    trendDaily[dayKey].net += amt;
  } else {
    totalDebit += amt;
    trendDaily[dayKey].debit += amt;
    trendDaily[dayKey].net -= amt;

    catAllTime[cat] = (catAllTime[cat] || 0) + amt;

    if (!isNaN(parsedMs) && parsedMs >= thirtyDaysAgoMs) {
      catMonthly[cat] = (catMonthly[cat] || 0) + amt;
      totalDebitMonth += amt;
    }

    if (!isNaN(parsedMs) && parsedMs >= sevenDaysAgoMs) {
      catWeekly[cat] = (catWeekly[cat] || 0) + amt;
      totalDebitWeek += amt;
    }
  }
});

// Calculate real streak
let currentStreak = 0;
const sortedUniqueDates = Array.from(uniqueActiveDates).sort().reverse();

if (sortedUniqueDates.length > 0) {
  const todayStr = now.toISOString().split('T')[0];
  const yesterday = new Date(nowMs - oneDayMs);
  const yesterdayStr = yesterday.toISOString().split('T')[0];

  let streakCheckDate = null;
  if (uniqueActiveDates.has(todayStr)) {
    streakCheckDate = new Date(todayStr);
  } else if (uniqueActiveDates.has(yesterdayStr)) {
    streakCheckDate = new Date(yesterdayStr);
  } else {
    const latestTxDate = new Date(sortedUniqueDates[0]);
    const diffDays = Math.floor((nowMs - latestTxDate.getTime()) / oneDayMs);
    if (diffDays <= 2) {
      streakCheckDate = latestTxDate;
    }
  }

  if (streakCheckDate) {
    while (true) {
      const dKey = streakCheckDate.toISOString().split('T')[0];
      if (uniqueActiveDates.has(dKey)) {
        currentStreak++;
        streakCheckDate.setDate(streakCheckDate.getDate() - 1);
      } else {
        break;
      }
    }
  } else {
    currentStreak = sortedUniqueDates.length > 0 ? 1 : 0;
  }
}

const colors = ["hsl(var(--chart-1))", "hsl(var(--chart-2))", "hsl(var(--chart-3))", "hsl(var(--chart-4))", "hsl(var(--chart-5))"];

const formatCat = (catDict, totalD) => {
  let colorIdx = 0;
  return Object.keys(catDict).map(c => {
    const val = catDict[c];
    return {
      category: c,
      total: Math.round(val * 100) / 100,
      percentage: totalD > 0 ? Number(((val / totalD) * 100).toFixed(1)) : 0,
      type: "debit",
      color: colors[(colorIdx++) % colors.length]
    };
  }).sort((a, b) => b.total - a.total);
};

const allTimeData = formatCat(catAllTime, totalDebit);
const monthlyData = Object.keys(catMonthly).length > 0 ? formatCat(catMonthly, totalDebitMonth) : allTimeData;
const weeklyData = Object.keys(catWeekly).length > 0 ? formatCat(catWeekly, totalDebitWeek) : monthlyData;

const dailyTrendArr = Object.values(trendDaily).sort((a, b) => a.date.localeCompare(b.date));
let rollingBalance = 50000;
dailyTrendArr.forEach(d => {
  rollingBalance += d.net;
  d.balanceAfter = rollingBalance;
  d.averageAccountBalance = rollingBalance;
});

// Parse insights / habit tips
let habitTips = [];
if (insights.length > 0) {
  const recentInsights = insights.slice(-2).reverse();
  recentInsights.forEach((row, i) => {
    let rawText = row.insights || row.paramData || row.insight || row.advice || "";
    let cleanCounsel = "";
    if (typeof rawText === "string") {
      rawText = rawText.trim();
      if (rawText.startsWith("{") || rawText.startsWith("[")) {
        try {
          const parsed = JSON.parse(rawText);
          cleanCounsel = parsed.counsel || parsed.advice || parsed.insights || parsed.analysis || parsed.summary || rawText;
        } catch (e) {
          cleanCounsel = rawText;
        }
      } else {
        cleanCounsel = rawText;
      }
    } else if (typeof rawText === "object" && rawText !== null) {
      cleanCounsel = rawText.counsel || rawText.advice || rawText.insights || rawText.analysis || JSON.stringify(rawText);
    }

    if (cleanCounsel) {
      habitTips.push({
        id: "habit-" + (i + 1),
        habitLabel: i === 0 ? "Latest Spending Analysis" : "Financial Coaching Tip",
        counsel: cleanCounsel,
        recordedAt: row.generatedAt || new Date().toISOString(),
        accent: i === 0 ? "primary" : "secondary"
      });
    }
  });
}

if (habitTips.length === 0) {
  habitTips.push({
    id: "habit-1",
    habitLabel: "Financial Coach",
    counsel: totalDebit > 0 
      ? "You have logged ₹" + totalDebit.toLocaleString('en-IN') + " across " + txs.length + " transactions. Keep tracking daily to preserve your " + currentStreak + "-day streak!"
      : "Welcome to SevAI! Start recording your daily income or expenses in Telegram to generate intelligent spending counsel.",
    recordedAt: new Date().toISOString(),
    accent: "primary"
  });
}

const todayStr = now.toISOString().split('T')[0];
const startDate = txDates.length > 0 ? new Date(Math.min(...txDates)).toISOString().split('T')[0] : todayStr;
const endDate = txDates.length > 0 ? new Date(Math.max(...txDates)).toISOString().split('T')[0] : todayStr;

const tableData = txs.slice(-15).reverse().map((t, i) => {
  const d = t.date_of_transaction || t.date || t.timestamp || '';
  const dateStr = parseSheetDate(d) || todayStr;
  const rawType = String(t.type || '').toLowerCase();
  const isIncome = rawType === 'credit' || rawType === 'income';
  const amtNum = parseFloat(String(t.amount || '').replace(/[^0-9.]/g, '')) || 0;

  return {
    id: t.row_number ? "#" + t.row_number : "TX-" + (i + 1),
    name: t.vendor || t.description || (isIncome ? "Income Deposit" : "Expense"),
    email: t.category || "General",
    status: isIncome ? "Income" : "Expense",
    amount: (isIncome ? "+₹" : "-₹") + amtNum.toLocaleString('en-IN'),
    rawAmount: amtNum,
    date: dateStr,
    type: isIncome ? "credit" : "debit"
  };
});

const response = {
  metadata: {
    generatedAt: now.toISOString(),
    currency: "INR"
  },
  account: {
    currentStreak: currentStreak,
    balance: {
      initial: 50000,
      current: 50000 + totalCredit - totalDebit,
      maxEverReached: 50000 + Math.max(0, totalCredit)
    }
  },
  transactions: {
    summary: {
      totalCount: txs.length,
      totalCredit: totalCredit,
      totalDebit: totalDebit,
      netFlow: totalCredit - totalDebit,
      dateRange: { start: startDate, end: endDate }
    },
    trend: { daily: dailyTrendArr },
    categoryBreakdown: {
      periods: {
        weekly: {
          currency: "INR",
          totalDebit: totalDebitWeek > 0 ? totalDebitWeek : totalDebit,
          label: "This Week",
          data: weeklyData
        },
        monthly: {
          currency: "INR",
          totalDebit: totalDebitMonth > 0 ? totalDebitMonth : totalDebit,
          label: "This Month",
          data: monthlyData
        },
        allTime: {
          currency: "INR",
          totalDebit: totalDebit,
          label: "All Time",
          data: allTimeData
        }
      }
    }
  },
  insights: {
    habitTips: habitTips,
    coachAdvice: []
  },
  paramInsights: {},
  wishlistItems: [],
  tableData: tableData
};

return [{ json: response }];
